BEGIN TRAN;

IF OBJECT_ID('tempdb..#KeepFemaleRegIds') IS NOT NULL DROP TABLE #KeepFemaleRegIds;
CREATE TABLE #KeepFemaleRegIds (OldRegId INT NOT NULL PRIMARY KEY);



IF OBJECT_ID('tempdb..#KeepUsers') IS NOT NULL DROP TABLE #KeepUsers;
SELECT DISTINCT ua.UserId
INTO #KeepUsers
FROM dbo.UserAccount ua
JOIN #KeepFemaleRegIds k
  ON ua.ProfileCode = CONCAT('SE', k.OldRegId);

DELETE up FROM dbo.UserProfile up WHERE NOT EXISTS (SELECT 1 FROM #KeepUsers k WHERE k.UserId = up.UserId);
DELETE uf FROM dbo.UserFamily uf WHERE NOT EXISTS (SELECT 1 FROM #KeepUsers k WHERE k.UserId = uf.UserId);
DELETE upho FROM dbo.UserPhoto upho WHERE NOT EXISTS (SELECT 1 FROM #KeepUsers k WHERE k.UserId = upho.UserId);
DELETE upref FROM dbo.UserPreference upref WHERE NOT EXISTS (SELECT 1 FROM #KeepUsers k WHERE k.UserId = upref.UserId);
DELETE usub FROM dbo.UserSubscription usub WHERE NOT EXISTS (SELECT 1 FROM #KeepUsers k WHERE k.UserId = usub.UserId);
DELETE l FROM dbo.Lead l WHERE NOT EXISTS (SELECT 1 FROM #KeepUsers k WHERE k.UserId = l.UserId);
DELETE psr FROM dbo.ProfileStatusReport psr WHERE NOT EXISTS (SELECT 1 FROM #KeepUsers k WHERE k.UserId = psr.ProfileUserId) OR (psr.ReportedByUserId IS NOT NULL AND NOT EXISTS (SELECT 1 FROM #KeepUsers k WHERE k.UserId = psr.ReportedByUserId)) OR (psr.ReviewedByUserId IS NOT NULL AND NOT EXISTS (SELECT 1 FROM #KeepUsers k WHERE k.UserId = psr.ReviewedByUserId));
DELETE ua FROM dbo.UserAccount ua WHERE NOT EXISTS (SELECT 1 FROM #KeepUsers k WHERE k.UserId = ua.UserId);

COMMIT;
